   69,
   101
  ]
 },
 {
  "name": "chain_of_command",
  "prose": "the principle that instructions with higher authority override those with lower authority, and that the assistant must follow applicable instructions under this ordering",
  "established_around": [
   11,
   67
  ]
 },
 {
  "name": "assistant_definition",
