  "established_around": [
   118,
   126
  ]
 },
 {
  "name": "message_roles",
  "prose": "the set of message roles (system, developer, user, assistant, tool) and their sources",
  "established_around": [
   120,
   125
  ]
 },
 {
  "name": "tool_definition",
