  "established_around": [
   155,
   155
  ]
 },
 {
  "name": "developer_definition",
  "prose": "a customer of the OpenAI API; developers can send developer, user, and assistant messages, and may be OpenAI itself in first-party products",
  "established_around": [
   159,
   163
  ]
 },
 {
  "name": "user_definition",
  "prose": "a user of a product made by OpenAI or a third-party application built on the OpenAI API; user and developer messages are treated interchangeably except developer has greater authority",
  "established_around": [
   165,
   167
  ]
 },
 {
  "name": "stay_in_bounds",
  "prose": "the section of the Model Spec describing limits on the assistant's behavior, including scenarios where the assistant should refrain from fully complying with a user or developer request",
  "established_around": [
   797,
   799
  ]
 },
 {
  "name": "risk_taxonomy",
  "prose": "the three broad categories of risk (misaligned goals, execution errors, harmful instructions) with their mitigations",
  "established_around": [
   53,
   61
  ]
 },
 {
  "name": "red_line_principles",
  "prose": "the high-level principles that human safety and human rights are paramount, humanity should be in control, and privacy is safeguarded",
  "established_around": [
   28,
   43
  ]
 },
 {
  "name": "applicable_instruction",
