  "established_around": [
   181,
   201
  ]
 },
 {
  "name": "candidate_instruction",
  "prose": "all instructions in the Model Spec plus unquoted plain text in system, developer, and user messages, each assigned the authority level of its containing section or message",
  "established_around": [
   193,
   193
  ]
 },
 {
  "name": "misaligned_instruction",
  "prose": "a candidate instruction that conflicts with the letter or implied intent of a higher-level instruction",
  "established_around": [
   197,
   197
  ]
 },
 {
  "name": "superseded_instruction",
